/* De onde começar a varredura.

   DOIS MODOS, o mesmo caminho depois daqui:

     manual     → id_from 0. Varre tudo o que a API entrega, do primeiro
                  pedido ao último. É a carga histórica.
     agendado   → começa no menor id dos últimos DIAS_JANELA dias que já
                  temos. Assim o pedido novo entra e o antigo que MUDOU de
                  status é relido, sem varrer o catálogo inteiro de 15 em
                  15 minutos.

   Por que id e não data: a paginação da Base é por id_from, e misturar os
   dois critérios numa chamada só é o tipo de coisa que ela aceita sem
   reclamar e ignora em silêncio — foi assim que o filter_order_status_id
   enganou a investigação de 22/08. */
const DIAS_JANELA = 7;

const _raiz = $getWorkflowStaticData('global');
if (!_raiz.ped) _raiz.ped = {};
const est = _raiz.ped;
est.iniciado = true;
est.lidos = 0; est.gravados = 0; est.semMudanca = 0; est.paginas = 0;
est.dataMaisAntiga = null; est.porOrigem = {};

/* O nome de cada canal sai da própria Base. Fixar uma lista aqui faria o
   pedido de uma loja nova aparecer com o código cru (melibr, shopeebr) até
   alguém lembrar de vir editar — e "todas as lojas" de um marketplace é
   justamente o que muda sem avisar. */
const fontes = {};
try {
  const s = $('Origens de venda').first().json || {};
  Object.entries(s.sources || {}).forEach(([tipo, lista]) => {
    Object.entries(lista || {}).forEach(([id, nome]) => {
      fontes[String(tipo).toLowerCase() + '/' + String(id)] = String(nome || '');
    });
  });
} catch (e) { console.log('AVISO: não consegui ler as origens — o canal vai sair como código.'); }

const nomeStatus = {};
try {
  ($('Status da Base').first().json.statuses || []).forEach(s => {
    nomeStatus[String(s.id)] = s.name || s.name_for_customer || '';
  });
} catch (e) { /* sem a lista, mostra o número */ }

/* O que já está gravado no LiveOps, para não regravar o que não mudou. */
let jaTemos = {};
try { jaTemos = $('O que já temos').first().json || {}; } catch (e) { jaTemos = {}; }
if (jaTemos && jaTemos.error) jaTemos = {};

/* Manual = carga completa. O gatilho de tempo não passa por "Começar
   agora", e é isso que distingue os dois sem precisar de flag na tela. */
let manual = true;
try { manual = !!$('Começar agora').first(); } catch (e) { manual = false; }

let idDe = 0;
if (!manual) {
  const corte = Date.now() - DIAS_JANELA * 86400000;
  let menor = null;
  Object.values(jaTemos).forEach(p => {
    if (!p || !p.data || !p.numero) return;
    const t = Date.parse(p.data + 'T12:00:00Z');
    if (!isFinite(t) || t < corte) return;
    const n = Number(p.numero);
    if (isFinite(n) && (menor === null || n < menor)) menor = n;
  });
  /* Sem nada na janela, varre tudo: é a primeira vez, ou a loja passou uma
     semana sem vender. Nos dois casos ler demais é melhor que ler de menos. */
  idDe = menor === null ? 0 : menor;
}

console.log('modo: ' + (manual ? 'carga completa' : 'janela de ' + DIAS_JANELA + ' dias')
  + ' | começando no id ' + idDe
  + ' | já temos ' + Object.keys(jaTemos).length + ' pedidos'
  + ' | canais conhecidos: ' + Object.keys(fontes).length);

return [{ json: { proximoId: idDe, fontes: fontes, nomeStatus: nomeStatus, jaTemos: jaTemos } }];

/* Uma página da Base vira registros do LiveOps.

   TODOS os canais, sem filtro de origem. O fluxo antigo pedia só o
   WhatsApp ao servidor; este lê tudo por dois motivos que já custaram caro
   uma vez: filtro com id errado devolve lista vazia SEM ERRO, e a carga
   terminaria "com sucesso" tendo importado zero; e lendo tudo o log mostra
   o nome que a Base dá a cada origem, que é como se descobre uma loja nova.

   O QUE ESTE FLUXO NÃO ALCANÇA — e nenhum outro alcança
   A Base move o pedido para o Arquivo depois de 3 meses, e o Arquivo é um
   BANCO SEPARADO, com busca própria. Nenhum parâmetro do getOrders chega
   lá: medido em 22/08/2026, date_from de janeiro e id_from 1 devolvem o
   mesmo pedido de 24/05. Os pedidos anteriores entram pela exportação em
   CSV da tela do Arquivo, no botão "Importar Arquivo" da aba Pedidos. */
const inicio = $('De onde começar').first().json;
const r = $json || {};
if (r.status && r.status !== 'SUCCESS') {
  throw new Error('A Base recusou a leitura: ' + (r.error_message || r.error_code || JSON.stringify(r).slice(0, 200)));
}
const pedidos = r.orders || [];

/* Os contadores do laço vivem no staticData, que é o único lugar que
   sobrevive de uma página para a outra. Mas ele NÃO chega aqui garantido:
   numa execução manual o n8n não promete que o objeto que "De onde começar"
   preencheu seja o mesmo que este nó recebe — e sem esta guarda a segunda
   passagem morria em "Cannot read properties of undefined", com a página já
   lida e jogada fora. Quem cria é quem usa. */
const _raiz = $getWorkflowStaticData('global') || {};
/* Gaveta própria: o outro ramo deste fluxo usa a dele, e sem isto os dois
   contadores somariam um no outro — o log mentiria num número que ninguém
   tem como conferir depois. */
if (!_raiz.ped) _raiz.ped = {};
const est = _raiz.ped;
if (!est.porOrigem) {
  est.iniciado = true;
  est.lidos = 0; est.gravados = 0; est.semMudanca = 0; est.paginas = 0;
  est.dataMaisAntiga = null; est.porOrigem = {};
}

if (!pedidos.length) {
  console.log('── varredura terminada ──');
  console.log(est.paginas + ' página(s) · ' + est.lidos + ' pedido(s) lidos · '
    + est.gravados + ' gravados · ' + est.semMudanca + ' sem mudança');
  console.log('pedido mais antigo alcançado: ' + (est.dataMaisAntiga || '—')
    + '  (a Base arquiva depois de 3 meses e não devolve arquivado pela API)');
  const ordem = Object.keys(est.porOrigem).sort((a, b) => est.porOrigem[b] - est.porOrigem[a]);
  console.log('canais: ' + ordem.map(k => k + '=' + est.porOrigem[k]).join(' · '));
  return [];
}

const TZ = 'America/Sao_Paulo';
function data(ts) {
  if (!ts) return '';
  return new Intl.DateTimeFormat('sv-SE', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' })
    .format(new Date(Number(ts) * 1000));
}
function hora(ts) {
  if (!ts) return '';
  return new Intl.DateTimeFormat('pt-BR', { timeZone: TZ, hour: '2-digit', minute: '2-digit' })
    .format(new Date(Number(ts) * 1000));
}
/* O total não vem pronto: a Base entrega produtos e frete separados. Somar
   aqui evita a tela mostrar valor diferente do que a Base mostra. */
function total(p) {
  const itens = (p.products || []).reduce((a, i) =>
    a + (Number(i.price_brutto) || 0) * (Number(i.quantity) || 0), 0);
  return Math.round((itens + (Number(p.delivery_price) || 0)) * 100) / 100;
}
const carimbo = new Date().toLocaleString('pt-BR', { timeZone: TZ,
  day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });

function igual(novo, antigo) {
  if (!antigo) return false;
  const campos = ['numero','externo','cliente','telefone','cpf','email','valor','itens','status','canal','data','hora','link'];
  return campos.every(k => String(antigo[k] === undefined ? '' : antigo[k]) === String(novo[k] === undefined ? '' : novo[k]));
}

const pagina = {};
let maiorId = inicio.proximoId;
let gravadosAqui = 0;

for (const p of pedidos) {
  est.lidos++;
  const id = Number(p.order_id) || 0;
  if (id > maiorId) maiorId = id;

  const fonte = String(p.order_source || '').toLowerCase();
  const idFonte = String(p.order_source_id === undefined || p.order_source_id === null ? '' : p.order_source_id);
  /* O nome da loja como a Base a chama — "Mercado Livre Suplelive", não
     "melibr". Sem o nome, o código cru; sem nem isso, "Outro". */
  const canal = inicio.fontes[fonte + '/' + idFonte] || inicio.fontes[fonte + '/'] || fonte || 'Outro';
  est.porOrigem[canal] = (est.porOrigem[canal] || 0) + 1;

  const quando = p.date_confirmed || p.date_add;
  const dia = data(quando);
  if (dia && (!est.dataMaisAntiga || dia < est.dataMaisAntiga)) est.dataMaisAntiga = dia;

  const registro = {
    id: 'base_' + p.order_id,
    numero: String(p.order_id),
    externo: String(p.external_order_id || p.shop_order_id || ''),
    cliente: p.delivery_fullname || p.invoice_fullname || p.user_login || '',
    telefone: String(p.phone || '').replace(/\D/g, ''),
    /* CPF/CNPJ é o invoice_nip na Base. É a primeira chave que a aba
       Clientes usa para juntar os pedidos da mesma pessoa. */
    cpf: String(p.invoice_nip || '').replace(/\D/g, ''),
    email: String(p.email || ''),
    valor: total(p),
    itens: (p.products || []).reduce((a, i) => a + (Number(i.quantity) || 0), 0),
    status: inicio.nomeStatus[String(p.order_status_id)] || ('status ' + p.order_status_id),
    canal: canal,
    data: dia,
    hora: hora(quando),
    link: 'https://panel-u.baselinker.com/orders.php#order:' + p.order_id,
    sincronizadoEm: carimbo,
    _by: 'n8n'
  };

  /* Regravar o que não mudou é escrita de D1 à toa, e faz a tela piscar
     sozinha. "Mudou" ignora o carimbo, senão todo pedido mudaria sempre. */
  if (igual(registro, inicio.jaTemos['base_' + p.order_id])) { est.semMudanca++; continue; }
  pagina['base_' + p.order_id] = registro;
  gravadosAqui++;
}

est.gravados += gravadosAqui;
est.paginas++;
console.log('página ' + est.paginas + ': ' + pedidos.length + ' lidos · ' + gravadosAqui + ' para gravar');

/* A Base entrega no máximo 100 por chamada. Página cheia significa que há
   mais — a próxima começa no id seguinte ao maior desta. */
return [{ json: { pagina: pagina, proximoId: maiorId + 1, temPagina: Object.keys(pagina).length > 0 } }];

/* De onde começar a varredura das notas.

   A nota fiscal é OUTRA tabela na Base, e o corte de 3 meses que esconde o
   pedido não vale para ela — medido em 01/09/2026 com a sonda 2: a primeira
   página trouxe 100 notas, todas anteriores ao corte, a mais antiga de
   junho/2025 e com order_id de 15,8 milhões (os arquivados da tela estão em
   37 milhões). É por aqui que o Arquivo entra, sem exportação manual.

   O QUE A NOTA TEM, e o que ela não tem:

     tem   order_id, data, valor, nome do cliente, CPF/CNPJ, endereço
     NÃO   telefone, e-mail, status do pedido, canal de venda

   Por isso estes pedidos entram marcados (deNotaFiscal) e NUNCA sobrescrevem
   um pedido que a API já trouxe inteiro. A nota preenche buraco, não manda
   em quem já está preenchido. */
const _raiz = $getWorkflowStaticData('global');
if (!_raiz.nf) _raiz.nf = {};
const est = _raiz.nf;
est.lidas = 0; est.gravados = 0; est.pulados = 0; est.paginas = 0;
est.maisAntiga = null; est.maisNova = null;

let jaTemos = {};
try { jaTemos = $('O que já temos (notas)').first().json || {}; } catch (e) { jaTemos = {}; }
if (jaTemos && jaTemos.error) jaTemos = {};

console.log('já temos ' + Object.keys(jaTemos).length + ' pedidos — a nota só preenche o que falta');
return [{ json: { proximaNota: 0, jaTemos: jaTemos } }];

/* Uma página de notas vira pedidos que faltavam.

   A regra de ouro: NÃO SOBRESCREVER. Ela é garantida em DOIS lugares, e o
   segundo é o que vale: aqui a foto de "o que já temos" evita o trabalho
   inútil, mas ela é tirada no começo da execução e envelhece enquanto o
   outro ramo grava. Quem garante de verdade é o ?somenteNovos=1 no nó de
   gravação — o worker recusa sobrescrever, aconteça o que acontecer no
   meio. Sem ele, a nota passava por cima do pedido bom e sumia o telefone. O pedido que a API trouxe tem
   telefone, status e canal; o reconstruído da nota não tem. Deixar a nota
   passar por cima seria trocar dado bom por dado pior, e ninguém perceberia
   — some o telefone de um cliente e a aba Clientes deixa de agrupar. */
const inicio = $('De onde começar (notas)').first().json;
const r = $json || {};
if (r.status && r.status !== 'SUCCESS') {
  throw new Error('A Base recusou as notas: ' + (r.error_message || r.error_code || JSON.stringify(r).slice(0, 200)));
}
const notas = r.invoices || [];

const _raiz = $getWorkflowStaticData('global') || {};
/* Gaveta própria: o outro ramo deste fluxo usa a dele, e sem isto os dois
   contadores somariam um no outro — o log mentiria num número que ninguém
   tem como conferir depois. */
if (!_raiz.nf) _raiz.nf = {};
const est = _raiz.nf;
if (est.lidas === undefined) {
  est.lidas = 0; est.gravados = 0; est.pulados = 0; est.paginas = 0;
  est.maisAntiga = null; est.maisNova = null;
}

if (!notas.length) {
  console.log('── varredura das notas terminada ──');
  console.log(est.paginas + ' página(s) · ' + est.lidas + ' nota(s) lidas · '
    + est.gravados + ' pedido(s) recuperados · ' + est.pulados + ' já existiam');
  console.log('período coberto: ' + (est.maisAntiga || '—') + ' até ' + (est.maisNova || '—'));
  return [];
}

const TZ = 'America/Sao_Paulo';
function dia(ts) {
  if (!ts) return '';
  return new Intl.DateTimeFormat('sv-SE', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' })
    .format(new Date(Number(ts) * 1000));
}
function hora(ts) {
  if (!ts) return '';
  return new Intl.DateTimeFormat('pt-BR', { timeZone: TZ, hour: '2-digit', minute: '2-digit' })
    .format(new Date(Number(ts) * 1000));
}
const carimbo = new Date().toLocaleString('pt-BR', { timeZone: TZ,
  day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });

const pagina = {};
let maiorNota = inicio.proximaNota;

for (const n of notas) {
  est.lidas++;
  const idNota = Number(n.invoice_id) || 0;
  if (idNota > maiorNota) maiorNota = idNota;

  const pedido = String(n.order_id || '').trim();
  if (!pedido || pedido === '0') continue;

  const chave = 'base_' + pedido;
  /* Já temos o pedido inteiro? A nota não tem nada a acrescentar. */
  if (inicio.jaTemos[chave]) { est.pulados++; continue; }
  /* Nem duas notas do mesmo pedido: a primeira que aparecer basta. */
  if (pagina[chave]) continue;

  const quando = Number(n.date_sell) || Number(n.date_add) || 0;
  const d = dia(quando);
  if (d) {
    if (!est.maisAntiga || d < est.maisAntiga) est.maisAntiga = d;
    if (!est.maisNova   || d > est.maisNova)   est.maisNova   = d;
  }

  pagina[chave] = {
    id: chave,
    numero: pedido,
    externo: '',
    cliente: String(n.invoice_fullname || n.invoice_company || '').trim(),
    telefone: '',
    /* invoice_nip é o CPF/CNPJ — a primeira chave que a aba Clientes usa
       para juntar os pedidos da mesma pessoa. É o campo mais valioso aqui:
       sem ele o histórico antigo não gruda em ninguém. */
    cpf: String(n.invoice_nip || '').replace(/\D/g, ''),
    email: '',
    valor: Math.round((Number(n.total_price_brutto) || 0) * 100) / 100,
    itens: 0,
    status: '',
    canal: '',
    data: d,
    hora: hora(quando),
    link: 'https://panel-u.baselinker.com/orders.php#order:' + pedido,
    /* De onde veio, e o que falta. doArquivo porque a API de pedidos não
       o alcança e ele não será relido; deNotaFiscal porque telefone, canal
       e status estarem vazios NÃO é defeito — a nota não os tem. */
    doArquivo: true,
    deNotaFiscal: true,
    notaFiscal: String(n.number || '') + (n.year ? ('/' + n.year) : ''),
    sincronizadoEm: carimbo,
    _by: 'n8n'
  };
  est.gravados++;
}

est.paginas++;
console.log('página ' + est.paginas + ': ' + notas.length + ' nota(s) · '
  + Object.keys(pagina).length + ' pedido(s) recuperados nesta');

return [{ json: { pagina: pagina, proximaNota: maiorNota + 1 } }];
